CREATE OR REPLACE FUNCTION public.campus_change_preferences(p_action text, p_value jsonb)
 RETURNS campus_user_preferences
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.campus_user_preferences; caller uuid:=auth.uid(); item jsonb; route_value jsonb;
  favorites text[]; routes jsonb; favorite_value text;
begin
  if caller is null then raise exception '请先登录，再同步个人收藏' using errcode='42501'; end if;
  if p_action is null or p_action not in ('add_favorite','remove_favorite','save_route','remove_route','import')
    or p_value is null or octet_length(p_value::text)>65000 then
    raise exception '收藏修改类型或内容无效' using errcode='23514'; end if;
  insert into public.campus_user_preferences(user_id) values(caller) on conflict(user_id) do nothing;
  select * into result from public.campus_user_preferences where user_id=caller for update;
  favorites:=result.favorite_ids; routes:=result.favorite_routes;
  if p_action in ('add_favorite','remove_favorite','remove_route') then
    if jsonb_typeof(p_value)<>'string' or char_length(p_value#>>'{}') not between 1 and 120 then
      raise exception '收藏地点或路线标识无效' using errcode='23514'; end if;
    favorite_value:=p_value#>>'{}';
    if p_action='add_favorite' then
      if not favorite_value=any(favorites) then favorites:=array_append(favorites,favorite_value); end if;
    elsif p_action='remove_favorite' then favorites:=array_remove(favorites,favorite_value);
    else
      select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into routes
        from jsonb_array_elements(routes) with ordinality where value->>'id'<>favorite_value;
    end if;
  elsif p_action='save_route' then
    route_value:=p_value;
    -- 先经既有触发器完整校验，防止被冲突去重掩盖不合法的输入。
    update public.campus_user_preferences set favorite_routes=jsonb_build_array(route_value) where user_id=caller;
    select coalesce(jsonb_agg(value order by ordinality),'[]'::jsonb) into routes
      from jsonb_array_elements(routes) with ordinality
      where value->>'id'<>route_value->>'id' and
        (value->>'originId',value->>'destinationId',value->>'mode') is distinct from
        (route_value->>'originId',route_value->>'destinationId',route_value->>'mode');
    routes:=routes||jsonb_build_array(route_value);
  else
    if jsonb_typeof(p_value)<>'object' or not (p_value ?& array['favoriteIds','savedRoutes'])
      or (p_value-array['favoriteIds','savedRoutes'])<>'{}'::jsonb
      or jsonb_typeof(p_value->'favoriteIds')<>'array' or jsonb_typeof(p_value->'savedRoutes')<>'array'
      or jsonb_array_length(p_value->'favoriteIds')>100 or jsonb_array_length(p_value->'savedRoutes')>100 then
      raise exception '导入收藏或路线的格式无效' using errcode='23514'; end if;
    for item in select value from jsonb_array_elements(p_value->'favoriteIds') loop
      if jsonb_typeof(item)<>'string' then raise exception '导入收藏地点无效' using errcode='23514'; end if;
      favorite_value:=item#>>'{}';
      if not exists(select 1 from public.campus_locations where id=favorite_value) then
        raise exception '导入收藏地点无效' using errcode='23514'; end if;
      if not favorite_value=any(favorites) then favorites:=array_append(favorites,favorite_value); end if;
    end loop;
    for route_value in select value from jsonb_array_elements(p_value->'savedRoutes') loop
      update public.campus_user_preferences set favorite_routes=jsonb_build_array(route_value) where user_id=caller;
      -- 保留云端相同路线；重复导入不会新增副本，也不会改动其他设备的新路线。
      if not exists(select 1 from jsonb_array_elements(routes) v where v->>'id'=route_value->>'id'
        or (v->>'originId',v->>'destinationId',v->>'mode')=
          (route_value->>'originId',route_value->>'destinationId',route_value->>'mode')) then
        routes:=routes||jsonb_build_array(route_value);
      end if;
    end loop;
  end if;
  update public.campus_user_preferences set favorite_ids=favorites,favorite_routes=routes where user_id=caller returning * into result;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.campus_complete_information_analysis(p_id uuid, p_token uuid, p_analysis jsonb, p_related_report_id uuid DEFAULT NULL::uuid, p_related_event_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j campus_private.information_jobs; r public.campus_reports; other public.campus_reports;
begin
  select * into j from campus_private.information_jobs where id=p_id and kind='analysis' and status='running'
    and claim_token=p_token and lease_until>now() for update;
  if not found then return false; end if;
  select * into r from public.campus_reports where id=j.target_id for update;
  if not found or r.status in ('withdrawn','resolved','rejected') then
    update campus_private.information_jobs set status='cancelled',claim_token=null where id=p_id; return false; end if;
  if octet_length(p_analysis::text)>12000 then raise exception '分析结果过长'; end if;
  update public.campus_reports set analysis=p_analysis,analysis_status='complete',status=case when status='submitted' then 'analyzed' else status end,
    related_report_id=p_related_report_id,related_event_id=p_related_event_id,updated_at=now() where id=r.id;
  if r.kind in ('lost','found') then
    insert into public.notifications(recipient_id,type,title,body,related_type,related_id,dedupe_key)
      select s.user_id,'lost-found','关注地点有新的失物信息','有同学发布寻物或招领，请打开软件核对物品特征。','lost-found',r.id::text,'lost-subscription:'||r.id::text
      from public.campus_subscriptions s where s.user_id<>r.author_id and s.location_id in ('',coalesce(r.location_id,''))
        and s.kind in ('',r.kind)
      on conflict(recipient_id,dedupe_key) where dedupe_key is not null do nothing;
  end if;
  if r.kind in ('lost','found') and p_related_report_id is not null then
    select * into other from public.campus_reports where id=p_related_report_id and author_id<>r.author_id
      and kind=case when r.kind='lost' then 'found' else 'lost' end and status in ('submitted','analyzed')
      and location_id=r.location_id and created_at>now()-interval '7 days';
    if found then
      insert into public.notifications(recipient_id,type,title,body,related_type,related_id,dedupe_key)
        values(r.author_id,'lost-found','发现可能匹配的失物信息','地点与物品描述接近，请核对特征后联系，匹配并不代表已确认归属。','lost-found',other.id::text,'lost-match:'||least(r.id::text,other.id::text)||':'||greatest(r.id::text,other.id::text)),
              (other.author_id,'lost-found','发现可能匹配的失物信息','地点与物品描述接近，请核对特征后联系，匹配并不代表已确认归属。','lost-found',r.id::text,'lost-match:'||least(r.id::text,other.id::text)||':'||greatest(r.id::text,other.id::text))
        on conflict(recipient_id,dedupe_key) where dedupe_key is not null do nothing;
    end if;
  end if;
  return public.campus_finish_information_job(p_id,p_token,null);
end $function$

CREATE OR REPLACE FUNCTION public.campus_process_repair(p_id uuid, p_status text, p_note text DEFAULT ''::text)
 RETURNS campus_reports
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.campus_reports; note text:=btrim(coalesce(p_note,''));
begin
  if auth.uid() is null or not coalesce(public.campus_is_manager(),false) then
    raise exception '仅管理员可处理报修' using errcode='42501'; end if;
  if p_status is null or p_status not in ('pending','processing','completed') or char_length(note)>120 then
    raise exception '请确认处理状态和不超过 120 字的说明' using errcode='23514'; end if;
  -- 与 worker 的完成接口保持相同锁顺序：先分析任务，再报告，避免互相等待。
  perform 1 from campus_private.information_jobs where kind='analysis' and target_id=p_id for update;
  select * into result from public.campus_reports where id=p_id for update;
  if not found or result.kind<>'repair' then raise exception '只能处理现有报修报告'; end if;
  if result.status in ('withdrawn','rejected') then raise exception '报修信息已撤回或失效'; end if;
  if result.repair_status='completed' and p_status<>'completed' then raise exception '已完成的报修不能回退；新问题请重新上报'; end if;
  if result.repair_status=p_status and result.repair_review_note=note then return result; end if;
  update public.campus_reports set repair_status=p_status,repair_review_note=note,repair_reviewed_by=auth.uid(),repair_updated_at=now(),
    status=case when p_status='completed' then 'resolved' else status end,
    updated_at=now()
    where id=p_id returning * into result;
  -- 管理状态使用独立列；保留原始 details，避免覆盖用户文字或突破其原有 12 KB 限制。
  if p_status='completed' then
    update campus_private.information_jobs set status='cancelled',claim_token=null,lease_until=null
      where kind='analysis' and target_id=p_id and status not in ('done','cancelled');
  end if;
  -- UPDATE 不触发 09 中的 after INSERT 分析队列，不重复分析已处理工单。
  insert into public.notifications(recipient_id,type,title,body,related_type,related_id,dedupe_key)
    values(result.author_id,'feedback-review',case p_status when 'completed' then '报修已完成' when 'processing' then '报修正在处理' else '报修等待处理' end,
      left(result.title||case when note='' then '' else '：'||note end,250),'feedback',result.id::text,
      'repair-status:'||result.id::text||':'||gen_random_uuid()::text)
    on conflict(recipient_id,dedupe_key) where dedupe_key is not null do nothing;
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.campus_review_report(p_id uuid, p_publish boolean, p_title text DEFAULT ''::text, p_summary text DEFAULT ''::text, p_location_id text DEFAULT NULL::text, p_kind text DEFAULT 'notice'::text, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_scope text DEFAULT 'subscribers'::text, p_event_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.campus_reports; result uuid; event_type text;
begin
  if not coalesce(public.campus_is_manager(),false) then raise exception '仅管理员可审核'; end if;
  select * into r from public.campus_reports where id=p_id for update;
  if not found or r.status in ('withdrawn','resolved','rejected') then raise exception '信息已失效'; end if;
  if r.event_id is not null then return r.event_id; end if;
  if not p_publish then update public.campus_reports set status='rejected',updated_at=now() where id=p_id; return null; end if;
  if p_kind in ('lost','found') then raise exception '失物信息请使用匹配流程'; end if;
  if p_scope not in ('all','subscribers') or p_kind not in ('construction','closure','water-power','crowd','notice','repair','feedback')
    or char_length(btrim(p_title)) not between 1 and 80 or char_length(btrim(p_summary)) not between 1 and 1500
    or p_location_id is null or p_end_at is null or p_end_at<=now() then raise exception '请确认标题、说明、地点和有效结束时间'; end if;
  -- 公共通行与停水停电通知不受订阅条件限制。
  if p_kind in ('construction','closure','water-power') then p_scope:='all'; end if;
  event_type:=case when p_kind in ('construction','closure','crowd') then p_kind else 'notice' end;
  if p_event_id is not null then
    update public.campus_events set title=btrim(p_title),impact=btrim(p_summary),end_at=p_end_at,
      information_revision=information_revision+1,information_scope=p_scope,updated_at=now()
      where id=p_event_id and source='community-reviewed' and location_id=p_location_id
        and information_kind=p_kind and status='active' returning id into result;
    if result is null then raise exception '关联事件不匹配，请新建通知'; end if;
  else
    insert into public.campus_events(author_id,location_id,type,title,impact,start_at,end_at,source,information_kind,information_scope,is_demo)
      values(auth.uid(),p_location_id,event_type,btrim(p_title),btrim(p_summary),now(),p_end_at,'community-reviewed',p_kind,p_scope,false)
      returning id into result;
  end if;
  update public.campus_reports set status='published',event_id=result,updated_at=now() where id=p_id;
  perform campus_private.issue_event_notices(result);
  return result;
end $function$

CREATE OR REPLACE FUNCTION public.campus_set_report_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare report public.campus_reports; caller uuid:=auth.uid();
begin
  if caller is null then raise exception '请先登录' using errcode='42501'; end if;
  if p_status is null or p_status not in ('withdrawn','resolved') then raise exception '状态不允许'; end if;
  if not exists(select 1 from public.campus_reports where id=p_id and author_id=caller) then
    raise exception '没有操作权限' using errcode='42501'; end if;
  perform 1 from campus_private.information_jobs where kind='analysis' and target_id=p_id for update;
  select * into report from public.campus_reports where id=p_id and author_id=caller for update;
  if not found then raise exception '没有操作权限' using errcode='42501'; end if;
  if p_status='resolved' and report.kind not in ('lost','found') then
    raise exception '报修处理和其他校园信息请由管理员确认结束；本人可撤回上报'; end if;
  if report.status=p_status then return; end if;
  update public.campus_reports set status=p_status,updated_at=now() where id=p_id;
  update campus_private.information_jobs set status='cancelled',claim_token=null,lease_until=null
    where kind='analysis' and target_id=p_id and status not in ('done','cancelled');
  -- 官方事件继续由管理员独立确认，不随单个报告撤回而消失。
end $function$
